use std::{fs, panic, path::Path, time::Instant};

fn main() {
    panic::set_hook(Box::new(|_| {}));
    let path = Path::new("/work/tmp/fuzz-input.just");
    let alphabet = b"a :=\n'\"{}()[]/\\#\r\t,@$+-!?";
    let mut seed = 0x13bd_a885_1234_5678_u64;
    let mut panics = 0;
    let start = Instant::now();
    for i in 0..300_000 {
        let len = if i < 10_000 { i % 5 } else { (seed as usize) % 120 };
        let mut source = String::new();
        for _ in 0..len {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            source.push(char::from(alphabet[(seed as usize) % alphabet.len()]));
        }
        if i % 4 == 0 {
            source = format!("x := {source}");
        }
        fs::write(path, &source).unwrap();
        if panic::catch_unwind(|| just::summary::summary(path)).is_err() {
            println!("PANIC input {source:?}");
            panics += 1;
            if panics == 10 {
                break;
            }
        }
        let _ = just::unindent(&source);
    }
    println!("panics={panics} elapsed={:?}", start.elapsed());
}
EOF
